-- 진행 중인 팝업/행사 (S_nov = 1.0)
INSERT INTO public.events (place_id, title, start_at, end_at, price, source, source_id)
SELECT id, name, NOW() - INTERVAL '3 days', NOW() + INTERVAL '30 days', price_min, 'MANUAL', source_id
FROM public.places WHERE source = 'MANUAL' AND source_id IN ('ss-04','yn-03','yn-11')
ON CONFLICT (source, source_id) DO NOTHING;
